class Tableau
{
    int*   donnees;
    size_t taille;
public:
    Tableau(const Tableau& autre);   // par copie
    Tableau(Tableau&& autre);        // par mouvement
};

// Copie : copie profonde — correct
Tableau::Tableau(const Tableau& autre)
{
    taille  = autre.taille;
    donnees = new int[taille];
    for (size_t i = 0; i < taille; i++)
        donnees[i] = autre.donnees[i];
}

// Mouvement : ?
Tableau::Tableau(Tableau&& autre)
{
    taille  = autre.taille;
    donnees = new int[taille];              // <-- suspect
    for (size_t i = 0; i < taille; i++)     // <-- suspect
        donnees[i] = autre.donnees[i];
}
